CREATE FUNCTION c1_private.ticket(n text,i c1_private.intents,e bigint) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE m jsonb;p jsonb=i.payload;c text;k text=i.action;mid text;op text='0x'||encode(sha256(convert_to(i.id::text,'UTF8')),'hex');args jsonb;BEGIN SELECT manifest->'stores'->(p->>'store') INTO m FROM c1_private.deployment WHERE ns=n;mid='0x'||encode(sha256(convert_to(p->>'meal','UTF8')),'hex');
 IF k='fund' THEN c=p->>'payer';args=jsonb_build_object('meal_id',mid,'version',(p->>'version')::bigint,'terms_hash',p->>'terms_hash','quantity',(p->>'quantity')::int,'unit_price',p->>'unit_price','amount',p->>'amount','deadline',(p->>'deadline')::bigint,'batch_id',p->>'batch_id','quote_id',p->>'quote_id');
 ELSIF k='publish' THEN c=m->>'catalog';args=jsonb_build_object('expected_control_revision',(p->>'controlRevision')::bigint,'meal_id',mid,'version',(p->>'version')::bigint,'terms',jsonb_build_object('price',p->>'price','terms_hash',p->>'terms_hash','body_digest',p->>'body_digest','image_digest',p->>'image_digest','windows',p->'windows','body_available',true,'image_available',true));
 ELSIF k='list' THEN k='listed';c=m->>'catalog';args=jsonb_build_object('expected_control_revision',(p->>'controlRevision')::bigint,'meal_id',mid,'listed',(p->>'listed')::boolean);
 ELSIF k='pause' THEN k='paused';c=m->>'catalog';args=jsonb_build_object('expected_control_revision',(p->>'controlRevision')::bigint,'paused',(p->>'paused')::boolean);
 ELSIF k='close' THEN c=m->>'catalog';args=jsonb_build_object('expected_control_revision',(p->>'controlRevision')::bigint);
 ELSIF k='issue' THEN c=m->>'issuer';args=jsonb_build_object('meal_id',mid,'expected_unit_seq',(p->>'seq')::int,'expected_next_generation',(p->>'generation')::bigint,'expected_terms_hash',p->>'terms_hash','deadline',(p->>'deadline')::bigint);
 ELSIF k IN('lock','handover','report','settle','expire') THEN c=CASE WHEN k='settle' THEN m->>'owner' WHEN k='expire' THEN m->>'issuer' ELSE m->>'operator' END;args=jsonb_build_object('voucher_id',p->>'voucher_id','generation',(p->>'generation')::bigint);IF k IN('lock','handover') THEN args=args||jsonb_build_object('deadline',(p->>'deadline')::bigint);END IF;IF k IN('handover','report') THEN args=args||jsonb_build_object('lock_id',p->>'lock_id');END IF;IF k='report' THEN args=args||jsonb_build_object('marker_id',p->>'marker_id');END IF;
 ELSIF k='refund' THEN c=p->>'payer';args=jsonb_build_object('batch_id',p->>'batch_id','mask',(p->>'mask')::int);ELSE PERFORM c1_private.fail('INVALID_ACTION');END IF;
 RETURN jsonb_build_object('ticket_id',i.id,'op_id',op,'kind',k,'caller',c,'payload',args,'payload_hash',NULL,'source_epoch',(SELECT source_epoch FROM c1_private.deployment WHERE ns=n),'fencing_epoch',e,'authorization_digest',encode(sha256(convert_to(jsonb_build_object('session',encode(i.session_hash,'hex'),'identity',i.identity_revision,'grant',i.grant_revision,'payer',i.payer_revision,'manual',p->>'manual_authorization')::text,'UTF8')),'hex'),'store',p->>'store');END $$;
CREATE FUNCTION c1_api.claim_job(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE j c1_private.outbox;i c1_private.intents;now_value bigint;BEGIN SELECT now INTO now_value FROM c1_private.deployment WHERE ns=n;SELECT * INTO j FROM c1_private.outbox WHERE ns=n AND state NOT IN('DONE','CLOSED','WAIT_ACTOR') AND lease_until<=now_value ORDER BY intent FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN jsonb_build_object('job',NULL);END IF;UPDATE c1_private.outbox SET worker=q->>'worker_id',lease_epoch=lease_epoch+1,lease_until=now_value+10 WHERE ns=n AND intent=j.intent RETURNING * INTO j;SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=j.intent;RETURN jsonb_build_object('job',jsonb_build_object('job_id',j.intent,'ticket_id',j.intent,'fencing_epoch',j.lease_epoch,'status',i.stage));END $$;
CREATE FUNCTION c1_private.stage(n text,op uuid,e bigint,actor boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE d c1_private.deployment;i c1_private.intents;s c1_private.sessions;gr bigint;t jsonb;m jsonb;BEGIN d=c1_private.guard(n);SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=op FOR UPDATE;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;IF EXISTS(SELECT 1 FROM c1_private.dispatch_tickets WHERE ns=n AND intent=op) THEN RETURN jsonb_build_object('ticket_id',op,'ticket',(SELECT payload FROM c1_private.dispatch_tickets WHERE ns=n AND intent=op),'manifest',d.manifest->'stores'->(i.payload->>'store'));END IF;PERFORM c1_private.guard(n,true);IF i.stage NOT IN('ACCEPTED','WAIT_ACTOR') OR actor IS DISTINCT FROM (i.action IN('fund','refund','settle')) THEN PERFORM c1_private.fail('FORBIDDEN');END IF;
 IF i.action IN('report','expire') THEN
 IF NOT EXISTS(SELECT 1 FROM c1_private.units u JOIN c1_private.intents original ON original.ns=u.ns AND original.id=(i.payload->>'parent_intent')::uuid WHERE u.ns=n AND u.store=i.payload->>'store' AND u.seq=(i.payload->>'seq')::int AND u.active_op=i.id AND u.voucher_id=i.payload->>'voucher_id' AND u.generation=(i.payload->>'generation')::numeric AND u.bucket='R' AND original.stage='FINAL_SUCCEEDED' AND ((i.action='report' AND original.action='handover' AND original.result->>'result'=u.marker_id AND u.marker_id=i.payload->>'marker_id' AND u.lock_id=i.payload->>'lock_id') OR (i.action='expire' AND original.action='issue' AND original.result->>'result'=u.voucher_id AND u.lock_id IS NULL AND u.marker_id IS NULL AND u.expires_at<=d.now))) THEN PERFORM c1_private.fail('ORIGINAL_CONTINUATION_REQUIRED');END IF;
 ELSE s=c1_private.auth(n,jsonb_build_object('session_hash',encode(i.session_hash,'hex')));IF s.subject<>i.principal OR s.identity_revision<>i.identity_revision THEN PERFORM c1_private.fail('REVOKED');END IF;END IF;
 IF i.action IN('publish','list','pause','close','lock','handover','settle') THEN gr=c1_private.owner_auth(n,s,i.payload->>'store',CASE WHEN i.action='settle' THEN 'payout' WHEN i.action IN('lock','handover') THEN 'redeem' ELSE 'catalog' END);IF gr IS DISTINCT FROM i.grant_revision THEN PERFORM c1_private.fail('REVOKED');END IF;END IF;
 IF i.action IN('fund','refund') AND NOT EXISTS(SELECT 1 FROM c1_private.payer_bindings WHERE ns=n AND subject=i.principal AND enabled AND revision=i.payer_revision) THEN PERFORM c1_private.fail('REVOKED');END IF;IF d.now>=i.deadline AND i.action NOT IN('report','expire') THEN PERFORM c1_private.fail('EXPIRED');END IF;
 IF i.action='issue' AND EXISTS(SELECT 1 FROM c1_private.units WHERE ns=n AND store=i.payload->>'store' AND bucket='R' AND expires_at<=d.now AND lock_id IS NULL AND marker_id IS NULL AND active_op IS NOT NULL AND active_op<>i.id) THEN PERFORM c1_private.fail('PENDING');END IF;
 IF i.action='handover' AND ((SELECT paused FROM c1_private.stores WHERE ns=n AND store=i.payload->>'store') OR NOT EXISTS(SELECT 1 FROM c1_private.units WHERE ns=n AND store=i.payload->>'store' AND seq=(i.payload->>'seq')::int AND lock_id=i.payload->>'lock_id' AND marker_id IS NULL)) THEN PERFORM c1_private.fail('NOT_LOCKED');END IF;
 IF i.action IN('fund','issue','publish') AND NOT c1_private.content_available(n,i.payload->>'store',i.payload->>'meal',(i.payload->>'version')::bigint) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;IF i.action IN('lock','handover','settle') AND NOT EXISTS(SELECT 1 FROM c1_private.units WHERE ns=n AND store=i.payload->>'store' AND seq=(i.payload->>'seq')::int AND c1_private.content_available(n,store,meal,version)) THEN PERFORM c1_private.fail('CONTENT_UNAVAILABLE');END IF;
 t=c1_private.ticket(n,i,e);INSERT INTO c1_private.dispatch_tickets VALUES(n,i.id,e,t,jsonb_build_object('session_revision',s.revision,'identity_revision',i.identity_revision,'grant_revision',i.grant_revision,'payer_revision',i.payer_revision),d.now);UPDATE c1_private.intents SET stage='DISPATCH_STARTED' WHERE ns=n AND id=op;IF actor THEN UPDATE c1_private.outbox SET state='OBSERVE_ONLY',lease_until=0 WHERE ns=n AND intent=op;END IF;RETURN jsonb_build_object('ticket_id',op,'ticket',t,'manifest',d.manifest->'stores'->(i.payload->>'store'));END $$;
CREATE FUNCTION c1_api.stage_job(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE j c1_private.outbox;BEGIN PERFORM c1_private.guard(n,true);SELECT * INTO j FROM c1_private.outbox WHERE ns=n AND intent=(q->>'job_id')::uuid FOR UPDATE;IF NOT FOUND OR j.worker<>q->>'worker_id' OR j.lease_epoch<>(q->>'fencing_epoch')::bigint OR j.lease_until<=(SELECT now FROM c1_private.deployment WHERE ns=n) THEN PERFORM c1_private.fail('STALE_LEASE');END IF;RETURN c1_private.stage(n,j.intent,j.lease_epoch,false);END $$;
CREATE FUNCTION c1_api.stage_actor(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ BEGIN RETURN c1_private.stage(n,(q->>'intent_id')::uuid,1,true);END $$;
CREATE FUNCTION c1_api.source_ticket(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE t c1_private.dispatch_tickets;i c1_private.intents;BEGIN SELECT * INTO t FROM c1_private.dispatch_tickets WHERE ns=n AND intent=(q->>'ticket_id')::uuid;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_STAGED');END IF;SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=t.intent;IF i.stage IN('DEFINITELY_UNEXECUTED','FINAL_REVERT','CANCELLATION_PENDING') THEN PERFORM c1_private.fail('CLOSED');END IF;RETURN jsonb_build_object('ticket',t.payload,'manifest',(SELECT manifest->'stores'->(i.payload->>'store') FROM c1_private.deployment WHERE ns=n));END $$;
CREATE FUNCTION c1_api.job_query(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE j c1_private.outbox;i c1_private.intents;d c1_private.deployment;BEGIN d=c1_private.guard(n);SELECT * INTO j FROM c1_private.outbox WHERE ns=n AND intent=(q->>'job_id')::uuid FOR UPDATE;IF NOT FOUND OR j.worker<>q->>'worker_id' OR j.lease_epoch<>(q->>'fencing_epoch')::bigint THEN PERFORM c1_private.fail('STALE_LEASE');END IF;IF coalesce((q->>'retry_unstaged')::boolean,false) THEN IF NOT EXISTS(SELECT 1 FROM c1_private.dispatch_tickets WHERE ns=n AND intent=j.intent) THEN UPDATE c1_private.outbox SET lease_until=d.now WHERE ns=n AND intent=j.intent;END IF;RETURN jsonb_build_object('retry',true);END IF;IF coalesce((q->>'heartbeat')::boolean,false) THEN UPDATE c1_private.outbox SET lease_until=d.now+10 WHERE ns=n AND intent=j.intent;RETURN jsonb_build_object('heartbeat',true);END IF;SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=j.intent;IF q->>'status'='UNKNOWN' AND i.stage IN('DISPATCH_STARTED','AWAITING_OUTCOME','UNKNOWN') THEN UPDATE c1_private.intents SET stage='UNKNOWN' WHERE ns=n AND id=i.id;END IF;RETURN jsonb_build_object('status',i.stage,'ticket_id',i.id);END $$;
CREATE FUNCTION c1_api.cancel_begin(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE i c1_private.intents;s c1_private.sessions;BEGIN PERFORM c1_private.guard(n);SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=coalesce(q->>'intent_id',q->>'job_id',q->>'ticket_id')::uuid FOR UPDATE;IF NOT FOUND THEN PERFORM c1_private.fail('NOT_FOUND');END IF;IF q ? 'session_hash' THEN s=c1_private.auth(n,q,true);IF i.principal<>s.subject OR i.action<>'fund' THEN PERFORM c1_private.fail('NOT_FOUND');END IF;END IF;IF q ? 'worker_id' AND NOT EXISTS(SELECT 1 FROM c1_private.outbox WHERE ns=n AND intent=i.id AND worker=q->>'worker_id' AND lease_epoch=(q->>'fencing_epoch')::bigint AND lease_until>(SELECT now FROM c1_private.deployment WHERE ns=n)) THEN PERFORM c1_private.fail('STALE_LEASE');END IF;IF i.stage='FINAL_SUCCEEDED' THEN RETURN jsonb_build_object('ticket_id',i.id,'observe_original',true);END IF;UPDATE c1_private.intents SET stage='CANCELLATION_PENDING' WHERE ns=n AND id=i.id;RETURN jsonb_build_object('ticket_id',i.id,'cancellation_id',encode(sha256(convert_to(i.id::text||i.client_request::text,'UTF8')),'hex'));END $$;
CREATE FUNCTION c1_api.cancel_finish(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE i c1_private.intents;BEGIN PERFORM c1_private.guard(n);SELECT * INTO i FROM c1_private.intents WHERE ns=n AND id=(q->>'ticket_id')::uuid FOR UPDATE;IF NOT FOUND OR i.stage<>'CANCELLATION_PENDING' OR q->'close_proof'->>'ticket_id'<>i.id::text OR NOT coalesce((q->'close_proof'->>'closed')::boolean,false) OR q->>'cancellation_id'<>encode(sha256(convert_to(i.id::text||i.client_request::text,'UTF8')),'hex') THEN PERFORM c1_private.fail('PROOF_MISMATCH');END IF;UPDATE c1_private.intents SET stage='DEFINITELY_UNEXECUTED',result=jsonb_build_object('fence',q->'close_proof') WHERE ns=n AND id=i.id;UPDATE c1_private.units SET active_op=NULL WHERE ns=n AND active_op=i.id;UPDATE c1_private.gates SET pending=NULL WHERE ns=n AND pending=i.id;UPDATE c1_private.outbox SET state='CLOSED' WHERE ns=n AND intent=i.id;RETURN jsonb_build_object('status','DEFINITELY_UNEXECUTED','ticket_id',i.id);END $$;

-- Derive only original lawful marker reports or safe expiry; callers choose no operation fields.
CREATE FUNCTION c1_api.continuation(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$
DECLARE d c1_private.deployment;u c1_private.units;original c1_private.intents;s c1_private.sessions;next_action text;op uuid;res jsonb;payload jsonb;
BEGIN
 d=c1_private.guard(n,true);
 SELECT * INTO u FROM c1_private.units WHERE ns=n AND bucket='R' AND active_op IS NULL AND (marker_id IS NOT NULL OR (lock_id IS NULL AND expires_at<=d.now AND NOT EXISTS(SELECT 1 FROM c1_private.intents pending WHERE pending.ns=n AND pending.action='issue' AND pending.payload->>'store'=units.store AND pending.stage NOT IN('FINAL_SUCCEEDED','FINAL_REVERT','DEFINITELY_UNEXECUTED')))) ORDER BY store,seq LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('created',false);END IF;
 next_action=CASE WHEN u.marker_id IS NOT NULL THEN 'report' ELSE 'expire' END;
 SELECT * INTO original FROM c1_private.intents WHERE ns=n AND stage='FINAL_SUCCEEDED' AND ((next_action='report' AND intents.action='handover' AND result->>'result'=u.marker_id) OR (next_action='expire' AND intents.action='issue' AND result->>'result'=u.voucher_id));
 IF NOT FOUND THEN PERFORM c1_private.fail('ORIGINAL_CONTINUATION_REQUIRED');END IF;
 SELECT * INTO s FROM c1_private.sessions WHERE ns=n AND hash=original.session_hash;
 IF NOT FOUND THEN PERFORM c1_private.fail('ORIGINAL_CONTINUATION_REQUIRED');END IF;
 op=gen_random_uuid();payload=jsonb_build_object('store',u.store,'seq',u.seq,'voucher_id',u.voucher_id,'generation',u.generation::bigint,'lock_id',u.lock_id,'marker_id',u.marker_id,'parent_intent',original.id,'deadline',u.expires_at);
 res=c1_private.new_intent(n,s,next_action,jsonb_build_object('new_id',op,'key','continuation:'||next_action||':'||original.id,'client',jsonb_build_object('original',original.id)),payload);
 UPDATE c1_private.units SET active_op=op WHERE ns=n AND store=u.store AND seq=u.seq;
 RETURN jsonb_build_object('created',true,'id',op);
END $$;
